root=Path(__file__).resolve().parents[2];out=root/'docs/protocolos/protese-anca-20261030';out.mkdir(parents=True,exist_ok=True)
uid=lambda k:str(uuid.uuid5(uuid.NAMESPACE_URL,'gc:protese-anca:2026-10-30:'+k));pid=uid('protocol')
sources=[{'title':'AAOS — exercício após prótese total da anca','url':'https://www.orthoinfo.org/recovery/total-hip-replacement-exercise-guide/'},{'title':'AAOS — atividade e precauções individualizadas','url':'https://www.orthoinfo.org/recovery/activities-after-hip-replacement'},{'title':'NICE NG157 — reabilitação após artroplastia primária','url':'https://www.nice.org.uk/guidance/ng157/chapter/Recommendations'},{'title':'Cambridge University Hospitals — cuidados e exercícios','url':'https://www.cuh.nhs.uk/patient-information/hip-replacement-total-advice-and-exercises-following/'}]
protocol={'id':pid,'region':'anca','name':'Artroplastia Total da Anca (Prótese Total) — recuperação domiciliária','kind':'cirurgico','is_active':True,'sort_order':14,'data':{'version':1,'versao_clinica':'2026-10-30','contextos':['Casa','Clínica','Ginásio'],'fontes':sources,'documento_base':'Exercícios - Anca - Recomendações Pós PTA.pdf — pasta fornecida pelo utilizador','status_revisao':'revisto_com_limites_e_restricoes_individuais_2026-10-30','nota_clinica':'PTA primária após alta, sem complicações, com carga e precauções confirmadas. Três fases por critérios, seis opções manuais por fase. Não aplicar automaticamente a revisão, fratura, osteotomia, reparação de abdutores, luxação ou complicações.','dose':'Doses iniciais práticas, não dose ótima validada. Reforço progressivo 3×12 quando tolerado; início reduzido, mobilidade 1×10, isométricos 5×10 s e equilíbrio 3×20 s. A seleção e as restrições individuais prevalecem.'}}
scope='Faça apenas os exercícios selecionados e a dose prescrita. As seis opções não são obrigatórias na mesma sessão. Este plano é para a recuperação após a alta; não substitui as instruções da equipa que o operou.'
protection='Confirme quanto pode apoiar e quais os movimentos temporariamente limitados. Não aumente o apoio, a amplitude ou a resistência por iniciativa própria. As restrições variam com a cirurgia; não há uma regra de 90 graus ou de cruzar pernas igual para todas as pessoas. Se recebeu essas restrições, cumpra-as pelo período indicado.'
gait='Use o andarilho ou as canadianas prescritas e previamente ajustadas. Faça trajetos curtos, com passos controlados. Com duas canadianas e apoio autorizado: avance os apoios, depois a perna operada e depois a outra, conforme o ensino recebido. Não abandone os auxiliares enquanto coxear, perder equilíbrio ou tiver restrição de carga.'
transfers='Prefira uma cadeira firme, estável e com braços, com a altura indicada pela equipa. Empurre os braços da cadeira para se levantar; não puxe pelas canadianas. Ao sentar, recue até sentir a cadeira atrás das pernas e desça com controlo. Coloque a perna operada ligeiramente à frente se isso facilitar, dentro das suas restrições.'
stairs='Treine primeiro com um profissional. Use o corrimão e o auxiliar na outra mão, conforme ensinado. Habitualmente, ao subir avança primeiro a perna não operada; ao descer, o auxiliar e a perna operada. Um degrau de cada vez. A técnica muda se não puder apoiar, tiver limitações na outra perna ou não houver corrimão: peça instruções próprias.'
daily='Entre e saia da cama e do carro com a técnica ensinada, mantendo o tronco e as pernas alinhados dentro dos limites prescritos. Para mudar de direção, dê pequenos passos em vez de rodar sobre o pé fixo. Use ajuda para vestir-se e calçar-se se necessário. As posições para dormir dependem das suas indicações; não force uma posição dolorosa.'
comfort='Intercale atividade com pausas e eleve confortavelmente a perna se ajudar no inchaço. Se aliviar, aplique frio protegido por toalha durante 10–15 minutos, sem adormecer e sem molhar ou pressionar a ferida. Confirme antes se tiver alterações de sensibilidade, circulação ou intolerância ao frio. Não massaje a ferida nem a barriga da perna inchada ou dolorosa.'
care='Siga os cuidados do penso e da ferida e a medicação da alta. Não interrompa o anticoagulante nem altere as meias de compressão prescritas sem orientação. Os exercícios do tornozelo não substituem a prevenção de trombose prescrita.'
response='Faça movimentos lentos e respire normalmente. Pare perante dor súbita, sensação de deslocação, falha ou perda de controlo. Se a dor, o inchaço ou a marcha estiverem claramente piores depois da sessão ou na manhã seguinte, reduza e contacte a equipa para ajustar. Não avance de fase só porque passaram dias ou semanas.'
alarm='Ligue 112 perante falta de ar súbita, dor no peito ou desmaio. Procure avaliação urgente perante dor súbita forte na anca com incapacidade de apoiar, deformidade, queda com dor importante, pé frio/pálido ou dor e inchaço novos na barriga da perna. Contacte a equipa cirúrgica no próprio dia perante febre, drenagem da ferida, vermelhidão crescente ou dor em agravamento.'
clinical=[{'title':'Confirmar antes de prescrever','text':'Registar lado, data, indicação da PTA, via cirúrgica, fixação, carga permitida, limites de movimento, reparações associadas, cicatrização, comorbilidades e auxiliares. Não basta selecionar a fase. A ausência de dados não equivale a ausência de restrições. Programa para PTA primária sem complicações; revisão/fratura/osteotomia/reparação de abdutores/luxação exigem adaptação específica.'},{'title':'Precauções por cirurgia, não universais','text':'Cumprir as indicações do cirurgião e os tempos de proteção dos tecidos, mesmo com boa função. Via posterior pode ter restrições prescritas de flexão/adução/rotação interna, sobretudo combinadas; via anterior pode limitar extensão/rotação externa; vias laterais e reparações de abdutores podem limitar abdução ativa ou resistida. Estes são exemplos para confirmar, não regras automáticas pela via. Não impor 90 graus a todos nem cancelar uma restrição por critérios funcionais.'},{'title':'Exercícios e carga','text':'Todos opcionais. Apoio unipodal, gémeos, cadeira e degrau só com carga autorizada. Não selecionar abdução ativa/resistida nem extensão ou ponte sem autorização para essa direção e fase. Após cirurgia evitar alongamentos de fim de amplitude, figura 4, pigeon e mobilizações forçadas do programa de coxartrose. Não fazer elevação da perna estendida de rotina no início.'},{'title':'Dose e progressão','text':'Doses práticas individualizáveis, não um ensaio validado de 3 fases/6 opções. Início com volume baixo; força até 3×12 se tolerada e autorizada; reduzir séries/repetições se necessário. Na mobilidade usar 1×10; isométricos 5×10 s; equilíbrio 3×20 s com apoio. Progressão depende de função, resposta, cicatrização e autorização, sem semanas fixas ou limiar numérico universal de dor.'},{'title':'Cuidados e referenciação','text':'Não substituir anticoagulação/profilaxia individual por exercícios. Não massajar suspeita de trombose. Dor nova/crescente, claudicação ou perda de função relacionadas com a prótese justificam contacto/referenciação cirúrgica; urgência se suspeita de luxação, fratura, infeção ou tromboembolismo. Não definir automaticamente alta de condução ou desporto por semanas.'}]
specs=[('1 — Proteção, autonomia e ativação inicial','Recuperar movimentos simples, transferências e marcha com os auxiliares indicados.',[('O seu plano',scope),('Proteção da prótese',protection),('Marcha e canadianas',gait),('Sentar e levantar',transfers),('Escadas',stairs),('Cama, carro e atividades diárias',daily),('Conforto e inchaço',comfort),('Ferida e medicação',care),('Como fazer e ajustar',response),('Sinais de alarme',alarm)],['Transferências e marcha curta seguras com o auxiliar e a carga prescritos.','Ativação e mobilidade toleradas, ferida e sintomas com evolução acompanhada; equipa autoriza exercícios em pé e direções selecionadas.']),('2 — Recuperar força, apoio e controlo','Melhorar o controlo nas tarefas habituais dentro das restrições.',[('O seu plano',scope),('Restrições e apoio',protection+' '+gait),('Reforço e equilíbrio','Reforço habitualmente em dias alternados, com a dose prescrita e apoio firme. Só faça afastamento da perna, extensão da anca ou apoio numa perna se autorizados. Pode manter as mãos apoiadas; não precisa de fechar os olhos.'),('Cuidados diários',transfers+' '+daily),('Ferida, medicação e conforto',care+' '+comfort),('Resposta ao exercício',response),('Sinais de alarme',alarm)],['Tarefas selecionadas com controlo e sem aumento persistente de dor, edema ou claudicação.','Força e equilíbrio em melhoria; cicatrização e proteção dos tecidos compatíveis, e autorização para resistência/degrau/bicicleta.']),('3 — Reforço progressivo e manutenção funcional','Aumentar a capacidade para caminhar, escadas e atividades importantes.',[('O seu plano',scope),('Restrições ainda em vigor',protection),('Frequência e progressão','Força habitualmente em 2–3 dias por semana, alternados. Aumente uma variável de cada vez: repetições, resistência ou duração. Mantenha os auxiliares se indicados. Se três séries forem excessivas, peça uma dose menor.'),('Caminhada, escadas e bicicleta','Mantenha caminhadas toleradas e progrida gradualmente. O degrau de exercício é diferente da técnica inicial de escadas com canadianas. Bicicleta só após autorização, com assento ajustado para respeitar o limite de flexão e entrada/saída seguras.'),('Regresso às atividades','Retome as atividades autorizadas aos poucos. Condução, natação, impacto e desporto precisam de decisão própria. Não entre em piscina antes de a ferida estar encerrada e de receber autorização.'),('Resposta e cuidados',response+' '+care),('Sinais de alarme',alarm)],['Rotina útil e sustentável, com controlo funcional e sem deterioração persistente.','Reavaliar objetivos, auxiliares e restrições com a equipa; conclusão desta fase não autoriza corrida, impacto ou desporto.'])]
phases=[]
